INSERT INTO materials VALUES(8,'Internet Sehat dan Aman','Teknologi','Pengenalan penggunaan internet secara aman dan bertanggung jawab.',replace('\n                <h3>Penggunaan Internet</h3>\n\n                <p>\n                    Internet dapat digunakan untuk mencari informasi,\n                    belajar, berkomunikasi, dan berbagai kegiatan positif.\n                </p>\n\n                <h3>Keamanan Internet</h3>\n\n                <p>\n                    Jangan membagikan password kepada orang lain\n                    dan berhati-hati ketika menerima informasi\n                    dari internet.\n                </p>\n            ','\n',char(10)),'materi',NULL,1,'2026-09-12 10:34:58','2026-09-12 10:34:58');
INSERT INTO page_contents VALUES(1,'home','{"hero":{"label":"RUANG BELAJAR \u2022 RUANG TUMBUH","title":"Bersama Membaca,","highlight":"Bersama Tumbuh.","description":"TBM Bintang Raharja hadir sebagai ruang belajar masyarakat yang mendorong budaya literasi, kreativitas, kebersamaan, dan pertumbuhan generasi melalui kegiatan yang positif.","primary_label":"Jelajahi Kegiatan","secondary_label":"Kenali TBM","focus":[{"label":"Fokus","value":"Literasi","icon":"books.png"},{"label":"Semangat","value":"Bertumbuh","icon":"growth.png"},{"label":"Berbasis","value":"Kebersamaan","icon":"handshake.png"}]},"intro":{"label":"TENTANG GERAKAN","title":"Sebuah ruang kecil untuk mimpi yang","highlight":"besar.","description":"Kami percaya bahwa perubahan tidak selalu dimulai dari sesuatu yang besar. Kadang, semuanya dimulai dari sebuah buku, sebuah kegiatan sederhana, dan seseorang yang mau berbagi ilmu.","link_label":"Pelajari perjalanan kami"},"activities":{"label":"Kegiatan","title":"Belajar Tidak Harus","highlight":"Membosankan.","description":"Berbagai kegiatan yang dirancang untuk menghadirkan pengalaman belajar yang menyenangkan dan bermakna.","link_label":"Lihat Semua Kegiatan"},"about":{"label":"Tentang Kami","title":"Tumbuh Bersama","highlight":"Melalui Literasi.","link_label":"Kenali TBM","paragraphs":["TBM Bintang Raharja merupakan ruang belajar masyarakat yang berfokus pada kegiatan literasi, pendidikan, dan pengembangan kreativitas anak-anak.","Melalui kegiatan bersama kakak pengajar, relawan, dan berbagai pihak yang berkolaborasi, anak-anak mendapatkan kesempatan untuk belajar, membaca, bermain, dan berkarya bersama."],"points":["Lingkungan belajar yang positif","Kegiatan literasi dan kreativitas","Kolaborasi bersama masyarakat"],"point_icons":["book.png","light bulb.png","handshake (2).png"]},"history":{"label":"Sejarah Kami","title":"Dari Baling-Baling","highlight":"hingga Bintang Raharja.","description":"Setiap perjalanan memiliki awal. Inilah bagian dari perjalanan yang membentuk identitas TBM Bintang Raharja.","items":[{"year":"Awal Perjalanan","title":"Berawal dari Semangat Literasi","description":"TBM Bintang Raharja berawal dari sebuah kegiatan dan kepedulian terhadap pentingnya pendidikan serta budaya membaca di lingkungan masyarakat."},{"year":"Fase Awal","title":"Baling-Baling","description":"Pada masa awal perkembangannya, gerakan ini dikenal dengan nama Baling-Baling. Nama tersebut menjadi bagian penting dari perjalanan awal sebelum berkembang menjadi TBM Bintang Raharja."},{"year":"Perkembangan","title":"Berkembang Menjadi Ruang Belajar","description":"Seiring berkembangnya kegiatan, ruang ini mulai menjadi tempat bagi anak-anak dan masyarakat untuk membaca, belajar, bermain, serta mengembangkan kreativitas."},{"year":"TBM Bintang Raharja","title":"Tumbuh Bersama Masyarakat","description":"Perjalanan tersebut kemudian berkembang menjadi TBM Bintang Raharja sebagai ruang belajar masyarakat yang membawa semangat membaca, belajar, berkarya, dan tumbuh bersama."}]},"values":{"label":"Nilai Kami","title":"Bukan Sekadar Tempat Membaca.","description":"Kami membangun ruang yang mendorong anak-anak untuk belajar, berinteraksi, dan berkembang.","items":[{"title":"Literasi","description":"Menumbuhkan kebiasaan membaca dan meningkatkan minat belajar melalui kegiatan yang menyenangkan.","icon":"literasi.png"},{"title":"Kreativitas","description":"Memberikan ruang bagi anak-anak untuk bereksperimen, berkarya, dan mengembangkan ide.","icon":"Kreativitas.png"},{"title":"Kebersamaan","description":"Membangun lingkungan belajar yang terbuka, ramah, dan saling mendukung.","icon":"kebersamaan.png"},{"title":"Pertumbuhan","description":"Mendukung perkembangan pengetahuan, keterampilan, dan karakter anak-anak.","icon":"pertumbuhan.png"}]},"impact":{"label":"Dampak","title":"Ruang yang","highlight":"Menghidupkan","title_suffix":"Potensi.","description":"Setiap kegiatan dirancang untuk memberikan pengalaman yang tidak hanya menyenangkan, tetapi juga memberikan ruang bagi anak-anak untuk berkembang.","items":[{"title":"Membaca","description":"Mengenalkan dan membangun kebiasaan membaca sejak dini."},{"title":"Belajar","description":"Menciptakan suasana belajar yang terbuka dan menyenangkan."},{"title":"Berkarya","description":"Memberikan ruang untuk menghasilkan karya dan mengembangkan kreativitas."},{"title":"Berkolaborasi","description":"Menghubungkan anak-anak, relawan, masyarakat, dan berbagai pihak."}]},"milestones":{"label":"Milestone","title":"Langkah yang Terus","highlight":"Bertumbuh.","description":"Perjalanan TBM Bintang Raharja dibangun dari langkah-langkah kecil yang dilakukan secara bersama-sama.","items":[{"title":"Memulai Gerakan","description":"Membangun ruang awal untuk kegiatan belajar dan literasi masyarakat."},{"title":"Mengembangkan Kegiatan","description":"Menghadirkan kegiatan membaca, belajar, bermain, dan berkarya."},{"title":"Memperluas Kolaborasi","description":"Membangun hubungan dengan relawan, masyarakat, dan berbagai pihak."},{"title":"Tumbuh Bersama","description":"Terus berkembang sebagai ruang belajar dan berkarya bagi masyarakat."}]},"partners":{"label":"Kolaborasi","title":"Bersama Membangun Generasi.","description":"TBM Bintang Raharja tumbuh melalui kolaborasi dengan berbagai pihak.","items":[{"name":"President University","icon":"President University.jpeg"},{"name":"Naresuan University","icon":"naresuan university.jpeg"},{"name":"Universiti Utara Malaysia","icon":"Universiti Utara Malaysia.png"},{"name":"Yayasan Bersatu Membangun Indonesia","icon":"Yayasan Bersatu Membangun Indonesia.jpeg"}]},"cta":{"eyebrow":"TBM BINTANG RAHARJA","title_first":"Satu Buku.","title_second":"Satu Ide.","title_third":"Satu Langkah Menuju Masa Depan.","description":"Bersama membaca, belajar, berkarya, dan menciptakan ruang tumbuh untuk generasi yang lebih baik.","activities_label":"Lihat Kegiatan","contact_label":"Hubungi Kami"},"stats":[{"number":"500+","label":"Buku","icon":"books.png"},{"number":"120+","label":"Peserta","icon":"audience.png"},{"number":"50+","label":"Kegiatan","icon":"calendar.png"},{"number":"10+","label":"Kolaborasi","icon":"handshake.png"}],"images":{"hero":"uploads\/home\/ffdf5820-1085-40d3-b6a0-47cc65b5f5e6.webp","about":"images\/tentang.jpeg"}}','2026-11-20 13:05:06','2026-11-20 13:12:44');
INSERT INTO page_contents VALUES(2,'contact','{"hero":{"label":"HUBUNGI KAMI","title":"Mari Terhubung","highlight":"Bersama TBM Bintang Raharja","description":"Punya pertanyaan mengenai kegiatan, program, atau ingin mengenal lebih jauh tentang TBM Bintang Raharja? Silakan hubungi kami.","card_title":"Hubungi TBM","card_description":"Kami terbuka untuk komunikasi dan informasi."},"people_heading":{"label":"KONTAK PERSON","title":"Terhubung Langsung","highlight":"Dengan Kami","description":"Silakan hubungi kontak person berikut untuk mendapatkan informasi mengenai kegiatan, program, kunjungan, maupun kolaborasi dengan TBM Bintang Raharja."},"information":{"label":"INFORMASI KONTAK","title":"Temukan Kami","description":"Informasi yang dapat membantu Anda terhubung dengan TBM Bintang Raharja.","cards":[{"icon":"\ud83d\udccd","title":"Lokasi","description":"Desa Karangharja, Cikarang Utara, Kabupaten Bekasi.","link_label":null,"link_route":null},{"icon":"\ud83d\udcda","title":"Kegiatan","description":"Informasi mengenai jadwal dan kegiatan dapat dilihat melalui halaman Kegiatan.","link_label":"Lihat Kegiatan \u2192","link_route":"activities.index"},{"icon":"\u2139\ufe0f","title":"Informasi","description":"Hubungi pengelola TBM untuk mendapatkan informasi lebih lanjut mengenai program dan kegiatan.","link_label":null,"link_route":null}]},"message":{"label":"PESAN UNTUK KAMI","title":"Ada yang ingin ditanyakan?","description":"Sampaikan pertanyaan atau pesan Anda melalui formulir di samping.","form_title":"Kirim Pesan","form_description":"Isi formulir berikut untuk menyampaikan pesan kepada TBM Bintang Raharja.","details":[{"icon":"\ud83d\udccd","title":"Alamat","description":"Desa Karangharja, Cikarang Utara, Kabupaten Bekasi."},{"icon":"\ud83d\udcc5","title":"Kegiatan","description":"Informasi jadwal kegiatan tersedia di halaman Kegiatan."},{"icon":"\ud83e\udd1d","title":"Terbuka untuk Kolaborasi","description":"TBM terbuka untuk komunikasi dan kerja sama yang mendukung kegiatan literasi."}]},"cta":{"eyebrow":"TBM BINTANG RAHARJA","title":"Mari belajar dan berkembang bersama.","description":"Ikuti kegiatan dan program TBM Bintang Raharja.","activities_label":"Lihat Kegiatan","login_label":"Masuk"},"people":[{"name":"Ibu Murni Setianingsih, S.Pd.","role":"Ketua TBM","description":"Ketua TBM Bintang Raharja","phone":"+62 813-1908-3960","email":null,"photo":"images\/bu murni.jpeg"},{"name":"Merlyn Sumardiyani","role":"Sekretaris 2","description":"Pengurus TBM Bintang Raharja","phone":"+62 895-3606-79144","email":"merlynsumardiyani47@gmail.com","photo":"images\/merlin.jpeg"},{"name":"Ashila Nur Fatihah","role":"Bendahara 2","description":"Pengurus TBM Bintang Raharja","phone":"+62 813-1835-6692","email":"ashilanurfatihah@gmail.com","photo":""}]}','2026-11-20 13:25:10','2026-11-20 13:25:10');
