PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "role" varchar not null default 'peserta', "points" integer not null default '0');
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" varchar not null, "queue" varchar not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "activities" ("id" integer primary key autoincrement not null, "title" varchar not null, "category" varchar not null, "description" text, "date" date not null, "start_time" time not null, "end_time" time not null, "instructor" varchar, "location" varchar, "image" varchar, "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, "instructor_photo" varchar);
CREATE TABLE IF NOT EXISTS "news" ("id" integer primary key autoincrement not null, "title" varchar not null, "category" varchar not null, "slug" varchar not null, "excerpt" text, "content" text not null, "author" varchar, "image" varchar, "published_at" date, "is_published" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "galleries" ("id" integer primary key autoincrement not null, "title" varchar not null, "category" varchar not null, "description" text, "image" varchar not null, "date" date, "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "materials" ("id" integer primary key autoincrement not null, "title" varchar not null, "category" varchar not null, "description" text, "content" text not null, "type" varchar not null default 'materi', "file" varchar, "is_published" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "about_pages" ("id" integer primary key autoincrement not null, "content" text not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "page_contents" ("id" integer primary key autoincrement not null, "slug" varchar not null, "content" text not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "attendances" ("id" integer primary key autoincrement not null, "user_id" integer not null, "activity_id" integer not null, "status" varchar check ("status" in ('hadir', 'tidak_hadir', 'izin')) not null default 'hadir', "note" text, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("activity_id") references "activities"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "user_material_progress" ("id" integer primary key autoincrement not null, "user_id" integer not null, "material_id" integer not null, "status" varchar check ("status" in ('belum_dibaca', 'sedang_dibaca', 'selesai')) not null default 'belum_dibaca', "completed_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("material_id") references "materials"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "achievements" ("id" integer primary key autoincrement not null, "title" varchar not null, "description" text, "icon" varchar not null default '🏆', "type" varchar check ("type" in ('kehadiran', 'materi', 'poin', 'khusus')) not null default 'khusus', "requirement_value" integer not null default '0', "reward_points" integer not null default '0', "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "user_achievements" ("id" integer primary key autoincrement not null, "user_id" integer not null, "achievement_id" integer not null, "earned_at" datetime not null default CURRENT_TIMESTAMP, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("achievement_id") references "achievements"("id") on delete cascade);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "cache_expiration_index" on "cache" ("expiration");
CREATE INDEX "cache_locks_expiration_index" on "cache_locks" ("expiration");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE INDEX "failed_jobs_connection_queue_failed_at_index" on "failed_jobs" ("connection", "queue", "failed_at");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE UNIQUE INDEX "news_slug_unique" on "news" ("slug");
CREATE UNIQUE INDEX "page_contents_slug_unique" on "page_contents" ("slug");
CREATE UNIQUE INDEX "attendances_user_id_activity_id_unique" on "attendances" ("user_id", "activity_id");
CREATE UNIQUE INDEX "user_material_progress_user_id_material_id_unique" on "user_material_progress" ("user_id", "material_id");
CREATE UNIQUE INDEX "user_achievements_user_id_achievement_id_unique" on "user_achievements" ("user_id", "achievement_id");
COMMIT;
